package com.example.starter.incident;

/**
 * 事件严重等级，S1 最高、S4 最低。
 */
public enum Severity {
    S1,
    S2,
    S3,
    S4
}

package com.example.starter.incident;

/**
 * 事件状态机；合法流转为 REPORTED -&gt; COMMANDING -&gt; CONTAINED -&gt; RESOLVED -&gt; CLOSED，
 * 不允许跳转或回退。
 */
public enum IncidentStatus {
    REPORTED,
    COMMANDING,
    CONTAINED,
    RESOLVED,
    CLOSED;

    /**
     * 返回合法的下一状态；已是终态（CLOSED）时返回 null。
     */
    public IncidentStatus next() {
        return switch (this) {
            case REPORTED -> COMMANDING;
            case COMMANDING -> CONTAINED;
            case CONTAINED -> RESOLVED;
            case RESOLVED -> CLOSED;
            case CLOSED -> null;
        };
    }
}

package com.example.starter.incident;

import org.springframework.http.HttpStatus;

/**
 * 业务异常，携带可区分的 HTTP 状态码：400 参数非法、404 不存在、409 权限或状态冲突、422 非法流转。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException invalidTransition(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

