package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件视图。commanderId 为 null 表示未接管；pendingCommanderId 为 null 表示无待交接。
 */
public record IncidentView(
        String incidentKey,
        Severity severity,
        String summary,
        String reporter,
        IncidentStatus status,
        String commanderId,
        String pendingCommanderId,
        Instant createdAt,
        Instant updatedAt) {

    public static IncidentView of(Incident incident) {
        return new IncidentView(
                incident.incidentKey(),
                incident.severity(),
                incident.summary(),
                incident.reporter(),
                incident.status(),
                incident.commanderId(),
                incident.pendingCommanderId(),
                incident.createdAt(),
                incident.updatedAt());
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 处置记录视图。
 */
public record ActionView(
        String actionKey,
        String actorId,
        Instant occurredAt,
        String type,
        String description,
        Instant createdAt) {

    public static ActionView of(IncidentAction action) {
        return new ActionView(
                action.actionKey(),
                action.actorId(),
                action.occurredAt(),
                action.actionType(),
                action.description(),
                action.createdAt());
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 历史流水视图。
 */
public record EventView(
        String eventType,
        String actorId,
        String fromStatus,
        String toStatus,
        String fromCommanderId,
        String toCommanderId,
        String detail,
        Instant createdAt) {

    public static EventView of(IncidentEvent event) {
        return new EventView(
                event.eventType(),
                event.actorId(),
                event.fromStatus(),
                event.toStatus(),
                event.fromCommanderId(),
                event.toCommanderId(),
                event.detail(),
                event.createdAt());
    }
}

package com.example.starter.incident;

import java.util.List;

/**
 * 事件完整历史视图：当前状态 + 处置记录 + 历史流水。
 */
public record IncidentHistoryView(
        IncidentView incident,
        List<ActionView> actions,
        List<EventView> events) {
}

