    private static final String EVENT_TOOK_COMMAND = "TOOK_COMMAND";
    private static final String EVENT_HANDOVER_INITIATED = "HANDOVER_INITIATED";
    private static final String EVENT_HANDOVER_ACCEPTED = "HANDOVER_ACCEPTED";
